from research_helpers import *
a=ev('https://www.sec.gov/Archives/edgar/data/925894/000092589403000020/symbolchangerelease.htm','Historical issuer names NanobacTX experimental regimen. Old issuer pathogen/efficacy assertions are not treated as established scientific facts or regulatory approvals.')
b=ev('https://ntrs.nasa.gov/api/citations/20070022849/downloads/20070022849.pdf','Primary research manuscript identifies Nano-Sero IgG and Nanocapture ELISA kits from Nanobac Oy,Finland,and anti-CNP8D10 antibody. Historical research use proves identities,not current clinical validity/authorization or present commercial supply.')
c=ev('https://ntrs.nasa.gov/api/citations/20070030847/downloads/20070030847.pdf?attachment=true','Primary manuscript authors affiliated with Nanobac Pharmaceuticals and NanobacOy describe company-associated assays and antibody; no diagnostic approval inferred from use in research.')
products=[p('NanobacTX','Historical experimental treatment regimen promoted by Nanobac; current continuation and clinical authorization unverified.',a,'unknown',aliases=['Nanobac TX']),p('Nano-Capture ELISA','Historical calcifying-particle antigen ELISA research assay; current commercial/clinical status unverified.',b,'unknown',roles=['commercial_partner'],typ='product',sub='diagnostics',aliases=['Nanocapture ELISA'],evidence=[b,c]),p('Nano-Sero IgG ELISA','Historical antibody-response ELISA research assay; current clinical authorization and availability unverified.',b,'unknown',roles=['commercial_partner'],typ='product',sub='diagnostics',evidence=[b,c]),p('Nanobac anti-CNP 8D10 monoclonal antibody','Historical research reagent used in tissue immunostaining; not a therapeutic antibody.',b,'unknown',roles=['commercial_partner'],typ='product',sub='research_tools',attributes={'clone':'8D10','use':'research_immunostaining'},evidence=[b,c])]
co=company('Nanobac Pharmaceuticals Incorporated',products,[a,b,c],'Four historically evidenced regimen/assay/reagent identities entered. Scientific disease-causation and efficacy claims not adopted; no current sale or FDA approval asserted. Current company/subsidiary rights,Calciclear relation,additional reagent SKUs and later assets/transactions still require reliable primary evidence. Forum/aggregator listings not used as sole proof.')
(out/'batch-0140.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
